// Staff permission check: the administration can do everything; a teacher only what the school allowed.
const can = perm => { const c = ctx(); return !c ? false : c.role !== 'teacher' ? ['owner', 'admin'].includes(c.role) : db.teacherCan(c.roleInfo.teacherId, perm); };

const today = () => new Date(db.days()[0]);
const sub = () => `${fmtDay(today())}${db.isHoliday() ? ` · <b style="color:var(--amber-ink)">عطلة (${esc(db.holidayName())})، البصمة ما تنحسب</b>` : ''} · ${esc(db.settings().schoolName)}`;

/* ============ LOGIN ============ */
// Password input with an eye toggle on the right (LTR text).
export function pwField(id, label, err = '', ac = 'current-password', help = '') {
  return `<label class="field ${err ? 'err' : ''}">${label}<div style="position:relative"><input class="input num" id="${id}" dir="ltr" type="password" autocomplete="${ac}" style="padding-right:46px" placeholder="••••••••"><button type="button" class="iconbtn" data-eye="${id}" aria-label="إظهار الرمز" aria-pressed="false" style="position:absolute;right:4px;top:50%;transform:translateY(-50%);width:36px;height:36px;min-height:36px;border:0;background:none;color:var(--muted)">${icon('eye', 20)}</button></div><span class="help">${esc(err || help)}</span></label>`;
}
export function bindEyes(root) {
  $$('[data-eye]', root).forEach(b => b.onclick = () => { const i = $('#' + b.dataset.eye, root); const show = i.type === 'password'; i.type = show ? 'text' : 'password'; b.innerHTML = icon(show ? 'eyeoff' : 'eye', 20); b.setAttribute('aria-label', show ? 'إخفاء الرمز' : 'إظهار الرمز'); b.setAttribute('aria-pressed', show); });
}
