/* ============ ATTENDANCE ============ */
const att = { day: null, sec: '', f: 'all', q: '' };
const attendance = {
  pickStudent(el, id) {
    const s = db.student(id); const sc = scope(); if (!s || (sc.sections && !sc.sections.includes(s.sectionId))) return false;
    att.sec = s.sectionId; att.q = s.name; att.f = 'all';
    const sel = $('#sec', el); if (sel) sel.value = att.sec; const q = $('#aq', el); if (q) q.value = att.q;
    $$('[data-f]', el).forEach(b => b.setAttribute('aria-pressed', b.dataset.f === 'all'));
    this.update(el); return true;
  },
  render(el) {
    const qs = new URLSearchParams(location.hash.split('?')[1] || '');
    if (qs.get('f')) att.f = qs.get('f');
    const sc = scope(); const secs = sc.sections ? db.sections().filter(s => sc.sections.includes(s.id)) : db.sections();
    if (sc.sections && !sc.sections.includes(att.sec)) att.sec = sc.sections[0];
    att.day = att.day || db.days()[0];
    el.innerHTML = topbar('الحضور والانصراف', sub()) + `
    <div class="card" style="display:flex;gap:10px;flex-wrap:wrap;align-items:flex-end">
      <label class="field" style="min-width:170px">اليوم<select class="input" id="day">${db.days().map((d, i) => `<option value="${d}" ${d === att.day ? 'selected' : ''}>${i === 0 ? 'اليوم · ' : ''}${fmtDay(new Date(d))}</option>`).join('')}</select></label>
      <label class="field" style="min-width:190px">الشعبة<select class="input" id="sec">${sc.sections ? '' : '<option value="">كل الشعب</option>'}${secs.map(s => `<option value="${s.id}" ${s.id === att.sec ? 'selected' : ''}>${esc(db.sectionLabel(s.id))}</option>`).join('')}</select></label>
      <label class="field" style="flex:1;min-width:180px">بحث بالاسم<input class="input" id="aq" value="${esc(att.q)}" placeholder="اكتب جزءاً من الاسم"></label>
    </div>
    <div class="seg" id="fseg" role="group" aria-label="تصفية حسب الحالة"></div>
    <div class="card tablewrap" id="tbl"></div>`;
    $('#day', el).onchange = e => { att.day = +e.target.value; this.update(el); };
    $('#sec', el).onchange = e => { att.sec = e.target.value; this.update(el); };
    $('#aq', el).oninput = e => { att.q = e.target.value; this.update(el); };
    el.addEventListener('click', e => {
      const f = e.target.closest('[data-f]'); if (f) { att.f = f.dataset.f; this.update(el); }
      const m = e.target.closest('[data-mark]'); if (m) { db.markManual(m.dataset.mark, ctx().name); toast('سُجّل الحضور يدوياً', db.student(m.dataset.mark).name); }
      const x = e.target.closest('[data-excuse]'); if (x) excuseModal(db.student(x.dataset.excuse));
    });
    this.update(el);
  },
  update(el) {
    const sc = scope();
    let list = db.students(att.sec || undefined);
    if (sc.sections) list = list.filter(s => sc.sections.includes(s.sectionId));
    const isToday = att.day === db.days()[0];
    const rows = list.map(s => ({ s, x: db.statusOf(s.id, att.day) }));
    const counts = { all: rows.length };
    rows.forEach(r => { counts[r.x.status] = (counts[r.x.status] || 0) + 1; if (r.x.late) counts.late = (counts.late || 0) + (r.x.status === 'left' ? 1 : 0); });
    const F = [['all', 'الكل'], ['present', 'حاضر'], ['late', 'متأخر'], ['absent', 'غائب'], ['excused', 'بعذر'], ['left', 'انصرف'], ...(isToday ? [['pending', 'لم يصل']] : [])];
    $('#fseg', el).innerHTML = F.map(([k, l]) => `<button data-f="${k}" aria-pressed="${att.f === k}">${l} <span class="num">${counts[k] || 0}</span></button>`).join('');
    const q = att.q.trim();
    const shown = rows.filter(r => (att.f === 'all' || r.x.status === att.f || (att.f === 'late' && r.x.late)) && (!q || r.s.name.includes(q)));
    $('#tbl', el).innerHTML = shown.length ? `<table><thead><tr><th>الطالب</th><th>الشعبة</th><th>الوصول</th><th>الانصراف</th><th>الطريقة</th><th>الحالة</th><th></th></tr></thead><tbody>
      ${shown.map(({ s, x }) => `<tr><td><a href="#/student/${s.id}" style="color:inherit;display:flex;gap:10px;align-items:center;text-decoration:none">${avatar(s.name, x.status, db.photoOf(s.id))}<b>${esc(s.name)}</b></a></td>
        <td class="muted">${esc(db.sectionShort(s.sectionId))}</td>
        <td class="num">${x.inEv ? `<button class="evlink" data-ev="${x.inEv.id}" title="إثبات الوصول">${fmtTime(x.inEv.ts)} ${icon('eye', 13)}</button>` : '—'}</td><td class="num">${x.outEv ? `<button class="evlink" data-ev="${x.outEv.id}" title="إثبات الانصراف">${fmtTime(x.outEv.ts)} ${icon('eye', 13)}</button>` : '—'}</td>
        <td class="muted small">${x.inEv ? esc(x.inEv.method) : x.excuse ? esc(x.excuse.reason) : '—'}</td>
        <td>${pill(x.status)}${x.status === 'left' && x.late ? ' ' + pill('late') : ''}</td>
        <td style="white-space:nowrap">${isToday && can('att') && (x.status === 'pending' || x.status === 'absent') ? `<button class="btn sm" data-mark="${s.id}">حضور يدوي</button> <button class="btn sm" data-excuse="${s.id}">عذر</button>` : ''}</td></tr>`).join('')}
      </tbody></table>` : `<div class="empty">لا يوجد طلاب بهذه الحالة</div>`;
  },
};

function excuseModal(s, onDone) {
  let reason = 'مريض';
  modal(`تبرير غياب: ${s.name}`, `
    <div class="seg" role="group" aria-label="السبب">${['مريض', 'ظرف عائلي', 'سفر', 'سبب آخر'].map(r => `<button data-r="${r}" aria-pressed="${r === reason}">${r}</button>`).join('')}</div>
    <label class="field">ملاحظة (اختياري)<textarea class="input" id="note" rows="3" style="padding:10px;min-height:80px"></textarea></label>
    <div class="muted small">يُسجَّل في المنصة تلقائياً ويصل لمربي الشعبة.</div>
    <button class="btn pr" id="send">إرسال التبرير</button>`, (m, close) => {
    m.addEventListener('click', e => { const b = e.target.closest('[data-r]'); if (b) { reason = b.dataset.r; $$('[data-r]', m).forEach(x => x.setAttribute('aria-pressed', x === b)); } });
    $('#send', m).onclick = () => { db.addExcuse(s.id, reason, $('#note', m).value.trim(), ctx().name); close(); toast('أُرسل التبرير', `${s.name} · ${reason}`); onDone?.(); };
  });
}

/* ============ STUDENTS ============ */
const stu = { q: '', sec: '' };
const students = {
  render(el) {
    const sc = scope(); const c = ctx();
    const secs = sc.sections ? db.sections().filter(s => sc.sections.includes(s.id)) : db.sections();
    el.innerHTML = topbar(c.role === 'teacher' ? 'طلابي' : 'الطلاب', sub(), ['owner', 'admin'].includes(c.role) ? `<button class="btn" id="impbtn">${icon('upload', 18)}استيراد من ملف</button><button class="btn pr" id="add">${icon('plus', 18)}إضافة طالب</button>` : '') + `
    <div class="card" style="display:flex;gap:10px;flex-wrap:wrap;align-items:flex-end">
      <label class="field" style="flex:1;min-width:200px">بحث<input class="input" id="sq" value="${esc(stu.q)}" placeholder="الاسم أو رقم الطالب"></label>
      <label class="field" style="min-width:200px">الشعبة<select class="input" id="ss"><option value="">الكل</option>${secs.map(s => `<option value="${s.id}" ${s.id === stu.sec ? 'selected' : ''}>${esc(db.sectionLabel(s.id))}</option>`).join('')}</select></label>
    </div><div class="card tablewrap" id="list"></div>`;
    $('#sq', el).oninput = e => { stu.q = e.target.value; this.update(el); };
    $('#ss', el).onchange = e => { stu.sec = e.target.value; this.update(el); };
    $('#add', el)?.addEventListener('click', () => addStudentModal());
    $("#impbtn", el)?.addEventListener('click', () => importModal());
    if (location.hash.includes('?add')) { history.replaceState(null, '', '#/students'); setTimeout(() => addStudentModal(), 50); }
    this.update(el);
  },
  update(el) {
    const sc = scope();
    let list = db.students(stu.sec || undefined);
    if (sc.sections) list = list.filter(s => sc.sections.includes(s.sectionId));
    if (stu.q.trim()) { const r = db.search(stu.q, sc).students; const ids = new Set(r.map(s => s.id)); list = stu.q.length > 1 ? db.students().filter(s => ids.has(s.id) || s.name.includes(stu.q)) : list; if (sc.sections) list = list.filter(s => sc.sections.includes(s.sectionId)); }
    const sorted = [...list].sort((a, b) => b.no - a.no);
    $('#list', el).innerHTML = `<div class="muted small" style="margin-bottom:6px">${list.length} طالباً</div><table><thead><tr><th>الطالب</th><th>الرقم</th><th>الشعبة</th><th>ولي الأمر</th><th>بصمة الوجه</th><th>اليوم</th></tr></thead><tbody>
      ${sorted.slice(0, 200).map(s => { const g = db.guardian(s.guardianId); const x = db.statusOf(s.id); return `<tr><td><a href="#/student/${s.id}" style="color:inherit;display:flex;gap:10px;align-items:center;text-decoration:none">${avatar(s.name, x.status, db.photoOf(s.id))}<b>${esc(s.name)}</b></a></td><td class="num">${s.no}</td><td class="muted">${esc(db.sectionShort(s.sectionId))}</td><td>${esc(g.name)}<div class="muted small num" dir="ltr" style="text-align:right">${maskPhone(g.phone)}</div></td><td>${s.face ? '<span class="pill p-present">مسجّلة</span>' : '<span class="pill p-pending">غير مسجّلة</span>'}</td><td>${pill(x.status)}</td></tr>`; }).join('')}
    </tbody></table>`;
  },
};

function addStudentModal(preSection = '') {
  const secs = db.sections();
  modal('إضافة طالب', `
    <form id="af" style="display:flex;flex-direction:column;gap:12px" novalidate>
      <label class="field" data-k="name">الاسم الرباعي<input class="input" name="name" placeholder="مثال: علي حسين كاظم جواد"><span class="help"></span></label>
      <label class="field" data-k="sectionId">الصف والشعبة<select class="input" name="sectionId"><option value="">اختر</option>${secs.map(s => `<option value="${s.id}" ${s.id === preSection ? 'selected' : ''}>${esc(db.sectionLabel(s.id))}</option>`).join('')}</select><span class="help"></span></label>
      <div class="grid g2" style="gap:12px">
        <label class="field" data-k="gName">اسم ولي الأمر<input class="input" name="gName"><span class="help"></span></label>
        <label class="field">صلة القرابة<select class="input" name="relation"><option>الأب</option><option>الأم</option><option>الأخ</option><option>آخر</option></select></label>
      </div>
      <label class="field" data-k="sPhone">رقم الطالب (اختياري)<input class="input num" name="sPhone" dir="ltr" data-phone inputmode="numeric" placeholder="إذا عنده هاتف خاص يدخل منه"><span class="help">رقم مختلف عن رقم ولي الأمر. لكل شخص رقم وحساب واحد.</span></label>
      <label class="field" data-k="gPhone">رقم ولي الأمر (للتحقق SMS)<input class="input num" name="gPhone" dir="ltr" placeholder="07XXXXXXXXX" data-phone inputmode="numeric"><span class="help">إذا الرقم مسجّل لطالب آخر، يُربط الطالبان بنفس الحساب.</span></label>
      <button class="btn pr" style="min-height:48px">حفظ وإرسال للأجهزة</button>
    </form>`, (m, close) => {
    $('#af', m).onsubmit = e => {
      e.preventDefault();
      const data = Object.fromEntries(new FormData(e.target));
      const r = db.addStudent(data);
      $$('[data-k]', m).forEach(f => { const k = f.dataset.k; f.classList.toggle('err', !!r.errors?.[k]); const h = $('.help', f); if (r.errors?.[k]) h.textContent = r.errors[k]; });
      if (!r.ok) return;
      close();
      toast(r.linked ? 'أُضيف الطالب وربط بحساب ولي أمر موجود' : 'أُضيف الطالب', `${r.student.name} · رقم البصمة ${r.student.deviceId}`);
      location.hash = `#/student/${r.student.id}`;
      // Straight to the face photo: the first capture becomes the student's reference picture.
      setTimeout(() => faceModal(r.student), 350);
    };
  });
}

/* ============ STUDENT PROFILE ============ */
const student = {
  render(el, id) {
    const s = db.student(id);
    const sc = scope();
    if (!s || (sc.sections && !sc.sections.includes(s.sectionId))) { el.innerHTML = topbar('غير متاح', '') + '<div class="card empty">هذا الطالب غير موجود أو خارج صلاحيتك.</div>'; return; }
    el.innerHTML = topbar(s.name, `${esc(db.sectionLabel(s.sectionId))} · رقم الطالب <span class="num">${s.no}</span>`) + `<div id="live" style="display:flex;flex-direction:column;gap:16px"></div>`;
    el.addEventListener('click', e => {
      if (e.target.closest('[data-face]')) faceModal(s);
      if (e.target.closest('[data-mark]')) { db.markManual(s.id, ctx().name); }
      if (e.target.closest('[data-excuse]')) excuseModal(s);
    });
    this.update(el, id);
  },
  update(el, id) {
    const s = db.student(id); const box = $('#live', el); if (!s || !box) return;
    const g = db.guardian(s.guardianId); const x = db.statusOf(s.id); const c = ctx();
    const evs = db.recentEvents(20, e => e.studentId === s.id).reverse();
    box.innerHTML = `<div class="split">
      <div class="card" style="display:flex;flex-direction:column;gap:12px">
        <div style="display:flex;gap:14px;align-items:center">${avatar(s.name, x.status, db.photoOf(s.id)).replace('class="av', 'style="width:64px;height:64px;font-size:24px" class="av')}<div style="flex:1"><h2>${esc(s.name)}</h2><div class="muted small">${esc(db.sectionLabel(s.sectionId))} · رقم البصمة <span class="num">${s.deviceId}</span></div></div>${pill(x.status)}</div>
        <h3>اليوم</h3>
        ${evs.length ? evs.map(e => `<div class="row"><span class="pill ${e.type === 'in' ? 'p-present' : 'p-left'}">${e.type === 'in' ? 'وصول' : 'انصراف'}</span><span class="num">${fmtTime(e.ts)}</span><span class="muted small" style="flex:1">${esc(e.method)}${e.deviceId ? ' · ' + esc(db.device(e.deviceId).name) : ''}</span><button class="btn sm" data-ev="${e.id}">${icon('eye', 14)}الإثبات</button></div>`).join('') : `<div class="muted">${x.status === 'excused' ? `غائب بعذر: ${esc(x.excuse.reason)}` : 'لا توجد بصمة اليوم بعد.'}</div>`}
        ${(x.status === 'pending' || x.status === 'absent') && c.role !== 'parent' ? `<div style="display:flex;gap:8px"><button class="btn" data-mark>حضور يدوي</button><button class="btn" data-excuse>تسجيل عذر</button></div>` : ''}
        <h3>آخر 20 يوم دراسي</h3>
        <div style="display:flex;gap:8px;flex-wrap:wrap">${db.days().slice(1).reverse().map(d => { const y = db.statusOf(s.id, d); return `<div style="text-align:center;flex:1;min-width:70px" class="card" ><div class="small muted">${dayName(new Date(d))}</div>${pill(y.status)}<div class="num small">${y.inEv ? fmtTime(y.inEv.ts) : '—'}</div></div>`; }).join('')}</div>
      </div>
      <div style="display:flex;flex-direction:column;gap:16px">
        <div class="card"><h3>ولي الأمر</h3><div class="row"><span style="flex:1"><b>${esc(g.name)}</b>${g.relation ? ` · ${esc(g.relation)}` : ''}</span><span class="num" dir="ltr">${['owner', 'admin'].includes(c.role) ? fmtPhone(g.phone) : maskPhone(g.phone)}</span></div>
          <div class="muted small">أولاده في المدرسة: ${db.childrenOf(g.id).map(k => esc(db.first(k.name))).join('، ')}</div></div>
        <div class="card"><h3>صورة بصمة الوجه</h3>
          ${(() => { const ph = db.photosOf(s.id); const first = ph[0], last = ph.length > 1 ? ph[ph.length - 1] : null; const canCap = ['owner', 'admin'].includes(c.role);
            if (!first) return `<div style="display:flex;gap:14px;align-items:center;margin:8px 0"><div class="facebox empty">${icon('child', 44)}</div><div style="flex:1"><div class="small muted">${s.face ? 'البصمة مسجّلة على الجهاز من قبل، بس ما أكو صورة محفوظة بالمنصة.' : 'ما انسجلت بصمة الوجه بعد.'}</div>${canCap ? `<button class="btn sm pr" data-face style="margin-top:8px">${icon('plus', 16)}التقاط الصورة الآن</button>` : ''}</div></div>`;
            return `<div style="display:flex;gap:14px;align-items:flex-start;margin:8px 0"><figure class="facebox"><img src="${first.data}" alt="صورة ${esc(s.name)} الأولى"><figcaption>الصورة الأولى</figcaption></figure>
              <div style="flex:1;min-width:0;display:flex;flex-direction:column;gap:6px"><div class="small"><b>انسجلت:</b> ${fmtDay(new Date(first.ts))} · <span class="num">${fmtTime(first.ts)}</span></div>${first.by ? `<div class="small"><b>بواسطة:</b> ${esc(first.by)}</div>` : ''}
                <div class="small muted">هذي أول صورة انأخذت للطالب وما تتغير أبداً، حتى تقارن بيها وتتأكد إنه نفس الطالب.</div>
                ${last ? `<div style="display:flex;gap:8px;align-items:center;margin-top:4px"><img src="${last.data}" alt="" style="width:46px;height:56px;object-fit:cover;border-radius:8px;border:1px solid var(--line)"><span class="small muted">آخر تحديث ${fmtDay(new Date(last.ts))}${last.by ? ' · ' + esc(last.by) : ''} (${ph.length - 1} تحديث)</span></div>` : ''}
                ${canCap ? `<button class="btn sm" data-face style="align-self:flex-start">تحديث الصورة</button>` : ''}</div></div>`; })()}
          ${db.devices().map(d => { const st = s.sync ? s.sync[d.id] : 'done'; return `<div class="row"><span style="flex:1">${esc(d.name)}</span>${st === 'done' ? '<span class="pill p-present">تمّت المزامنة</span>' : st === 'queued' ? '<span class="pill p-late">بانتظار الاتصال</span>' : '<span class="pill p-pending">جاري الإرسال…</span>'}</div>`; }).join('')}
          <div class="muted small" style="margin-top:6px">صورة الوجه تُرسل للجهاز فيصنع منها البصمة، والبصمة نفسها تبقى داخل الجهاز.</div></div>
      </div></div>`;
  },
};

// Face capture with the device camera. The frame is grabbed at the green level and saved as a small JPEG;
// the first one becomes the student's reference photo.
function faceModal(s) {
  const c = ctx(); const by = `${c.name}${db.credOf(c.phone)?.username ? ' · ' + db.credOf(c.phone).username : ''}`;
  modal(db.photoOf(s.id) ? 'تحديث صورة الوجه' : 'صورة بصمة الوجه', `
    <div id="cam" style="height:280px;border-radius:16px;background:#1E2B5C;display:flex;align-items:center;justify-content:center;position:relative;overflow:hidden">
      <video id="vid" playsinline muted style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transform:scaleX(-1);display:none"></video>
      <svg width="190" height="230" viewBox="0 0 230 280" aria-hidden="true" style="position:relative"><ellipse cx="115" cy="130" rx="82" ry="108" fill="none" stroke="#34C3AE" stroke-width="4" stroke-dasharray="10 8"/></svg>
      <span class="pill" id="fq" style="position:absolute;top:12px;right:12px;background:var(--red);color:var(--on-red)">غير واضح</span>
      <span id="camnote" class="small" style="position:absolute;bottom:10px;inset-inline:10px;text-align:center;color:#DDE3F5">جاري فتح الكاميرا…</span></div>
    <div><div style="display:flex;justify-content:space-between;font-weight:700;font-size:14px"><span>وضوح الوجه</span><span id="fqt">اقترب من الكاميرا</span></div>
      <div style="display:flex;gap:4px;height:14px;margin-top:8px" id="meter"><i style="flex:1;border-radius:0 7px 7px 0;background:var(--surface-300)"></i><i style="flex:1;background:var(--surface-300)"></i><i style="flex:1;border-radius:7px 0 0 7px;background:var(--surface-300)"></i></div>
      <div style="display:flex;font-size:12px;font-weight:700;text-align:center;margin-top:4px"><span style="flex:1;color:var(--red-ink)">غير واضح</span><span style="flex:1;color:var(--amber-ink)">اقترب قليلاً</span><span style="flex:1;color:var(--teal-ink)">واضح</span></div></div>
    ${db.photoOf(s.id) ? '<div class="small muted">الصورة الأولى تبقى محفوظة مثل ما هي. هذي تنضاف كتحديث.</div>' : '<div class="small muted">هذي الصورة تصير الصورة المرجعية للطالب، وتظهر للإدارة حتى تقارن بيها.</div>'}
    <button class="btn pr" id="cap" disabled>التقاط الصورة</button>`, (m, close) => {
    const bars = $$('#meter i', m); const colors = ['var(--red)', 'var(--amber)', 'var(--teal)']; const txt = ['اقترب من الكاميرا', 'اقترب قليلاً', 'واضح · جاهز للالتقاط'];
    const vid = $('#vid', m); let stream = null, lvl = -1, iv = null;
    const stop = () => { clearInterval(iv); stream?.getTracks().forEach(t => t.stop()); };
    const watch = setInterval(() => { if (!document.body.contains(m)) { stop(); clearInterval(watch); } }, 500);
    const step = () => { lvl = Math.min(2, lvl + 1); bars.forEach((b, i) => b.style.background = i === lvl ? colors[i] : 'var(--surface-300)'); $('#fqt', m).textContent = txt[lvl]; const fq = $('#fq', m); fq.textContent = ['غير واضح', 'مقبول', 'واضح ✓'][lvl]; fq.style.background = colors[lvl]; if (lvl === 2) { clearInterval(iv); $('#cap', m).disabled = false; } };
    const grab = () => {
      if (!stream || !vid.videoWidth) return null;
      const W = 240, H = 300, cv = document.createElement('canvas'); cv.width = W; cv.height = H; const g = cv.getContext('2d');
      const vw = vid.videoWidth, vh = vid.videoHeight, r = W / H; let sw = vh * r, sh = vh; if (sw > vw) { sw = vw; sh = vw / r; }
      g.translate(W, 0); g.scale(-1, 1); g.drawImage(vid, (vw - sw) / 2, (vh - sh) / 2, sw, sh, 0, 0, W, H);
      return cv.toDataURL('image/jpeg', 0.82);
    };
    const save = () => { const data = grab(); stop(); db.captureFace(s.id, data, by); close(); toast(data ? 'انحفظت صورة الوجه' : 'سُجّلت بصمة الوجه', data ? 'تُرسل للأجهزة، وتظهر بملف الطالب' : 'الكاميرا ما اشتغلت، فما انحفظت صورة'); };
    (async () => {
      try {
        if (!navigator.mediaDevices?.getUserMedia) throw new Error('no camera');
        stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user', width: { ideal: 640 } }, audio: false });
        if (!document.body.contains(m)) { stop(); return; }
        vid.srcObject = stream; vid.style.display = 'block'; await vid.play(); $('#camnote', m).textContent = 'خلي الوجه بالنص، بدون نظارة شمسية أو كمامة';
      } catch { $('#camnote', m).textContent = 'الكاميرا مو متاحة هنا. افتح المنصة بالمتصفح واسمح للكاميرا.'; }
      iv = setInterval(step, 900); step();
    })();
    $('#cap', m).onclick = save;
  });
}

