    <div class="card" style="padding:10px 12px;background:var(--surface-300);border:0" class="small">ينكتب باسمك: <b>${esc(me.name)}</b>${me.username ? ` · <span class="num" dir="ltr" style="font-weight:700">${esc(me.username)}</span>` : ''}</div>
