    f.onsubmit = e => { e.preventDefault(); if (f.value.value === '') { const x = $('[data-k="value"]', el); x.classList.add('err'); $('.help', x).textContent = 'اكتب الدرجة، أو اضغط «حذف الدرجة».'; return; } submit(f.value.value); };
    $('#delm', el)?.addEventListener('click', () => submit(null));
